package com.atlasiq.security;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.enterprise.inject.Instance;import java.util.*;
@ApplicationScoped public class SecurityPostureService {private final AnalysisStore store;private final List<VulnerabilitySource> sources;public SecurityPostureService(AnalysisStore s,Instance<VulnerabilitySource> v){store=s;sources=v.stream().toList();}
 public Posture analyze(String id){QirModel m=store.find(id).orElseThrow().model();List<VulnerablePackage> vulns=new ArrayList<>();for(QirNode p:m.nodes())if("software-package".equals(p.type())){List<Vulnerability> found=sources.stream().flatMap(s->s.query(p).stream()).distinct().toList();if(!found.isEmpty())vulns.add(new VulnerablePackage(p.id(),p.name(),found,correlate(m,p.id())));}List<Finding> sec=m.findings().stream().filter(f->"security".equalsIgnoreCase(f.category())).toList();int critical=(int)vulns.stream().flatMap(v->v.vulnerabilities().stream()).filter(v->Set.of("critical","high").contains(v.severity())).count();int score=Math.max(0,100-critical*15-sec.size()*5);return new Posture(id,score,score>=90?"good":score>=70?"attention":"high-risk",List.copyOf(vulns),sec);}
 private Impact correlate(QirModel m,String packageId){Set<String> ids=new LinkedHashSet<>(List.of(packageId));boolean changed=true;while(changed){changed=false;for(QirEdge e:m.edges())if(ids.contains(e.to())&&Set.of("depends_on","contains","runs","deployed_as","observed_as","owned_by").contains(e.relationship()))changed|=ids.add(e.from());}List<QirNode> n=m.nodes().stream().filter(x->ids.contains(x.id())).toList();return new Impact(n.stream().filter(x->Set.of("service","component","repository").contains(x.type())).map(QirNode::id).toList(),n.stream().filter(x->x.type().contains("runtime")||x.type().startsWith("kubernetes-")).map(QirNode::id).toList(),n.stream().filter(x->Set.of("team","owner").contains(x.type())).map(QirNode::id).toList());}
 public record VulnerablePackage(String packageId,String packageName,List<Vulnerability> vulnerabilities,Impact impact){}public record Impact(List<String> services,List<String> runtime,List<String> teams){}public record Posture(String analysisId,int score,String status,List<VulnerablePackage> vulnerablePackages,List<Finding> securityFindings){}
}